def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bands = [r for r, row in enumerate(g) if all(v == row[0] and v == 2 for v in row)]
    if not bands:
        return g
    band = bands[0]
    points = [(r, c, v) for r in range(h) for c, v in enumerate(g[r]) if v not in (4, 2, 8)]
    if not points:
        return g
    lo, hi = min(r for r,c,v in points), max(r for r,c,v in points)
    # Move the small object adjacent to the full-width band; paint its traversed row(s) 8.
    dr = (band - 1 - hi) if hi < band else (band + 1 - lo)
    for r,c,v in points:
        g[r][c] = 4
    for r in range(lo, hi + 1):
        dest = r + dr
        if lo <= r <= hi and not (lo + dr <= dest <= hi + dr):
            continue
    # Color rows traversed, excluding original and destination object rows.
    for r in range(min(lo, lo+dr), max(hi, hi+dr)+1):
        if not (lo <= r <= hi) and not (lo+dr <= r <= hi+dr):
            g[r] = [8] * w
    for r,c,v in points:
        g[r+dr][c] = v
    return g
